      "跨日科技投票截止时间必须早于游戏每日刷新时间": "For an overnight technology vote, the cutoff must be before the next game refresh.",
      "减少 Worker 请求的建议": "Suggestions for reducing Worker requests",
      "旧版分时轮询窗口 JSON（仅兼容保存，不作为任务唤醒依据）": "Legacy time-window polling JSON (kept for compatibility; not used for task wakeups)",
      "任务时间前后活跃窗口（分钟）": "Active window around task time (minutes)",
      "空闲轮询可设为 300–600 秒；实际任务窗口内建议 15–30 秒，仅保留确实会执行任务的窗口。任务执行中轮询可保持 10–15 秒，以兼顾响应速度。": "Set idle polling to 300–600 seconds and polling inside real task windows to 15–30 seconds; keep only windows that are actually needed. Active-task polling can stay at 10–15 seconds for responsiveness.",
      "下方 JSON 只控制本地 Agent 何时向 Worker 请求任务及请求间隔，不是任务执行时间；窗口外会使用默认空闲轮询。": "The JSON below only controls when the local Agent asks the Worker for work and how often; it does not schedule tasks. The default idle interval is used outside these windows.",
      "Agent 会从任务计划中的启用任务时间自动生成活跃窗口，默认覆盖每个任务时间前后 15 分钟；窗口内保持 Workers-Agent 交互，窗口外进入懒惰状态并直接睡到下一个窗口。": "The Agent derives active windows from enabled task times, covering 15 minutes before and after each task by default. It stays connected inside a window and sleeps until the next window outside it.",
      "手动点击 Mac Agent 左下角“恢复活跃”可随时解除懒惰；再次点击“解除活跃”恢复懒惰。定时任务窗口仍会自动唤醒，进入窗口后先向 Workers 请求最新计划再开始工作。": "Click Restore activity in the Mac Agent to leave lazy mode; click Enter lazy mode to return. Scheduled windows still wake the Agent, which fetches the latest plan before working.",
      "下方旧版 JSON 保留用于兼容已有配置，不再决定自动任务的唤醒时间；请使用上方的活跃窗口分钟数和任务计划设置。": "The legacy JSON below is retained for existing configurations but no longer controls automatic task wakeups; use the active-window and task-schedule settings above.",
      "审批": "Approve",
      "审批延期申请": "Approve renewal request",
      "审批重新发行申请": "Approve reissue request",
      "未知配置分区": "Unknown configuration section",
      "申请类型": "Application type",
      "每人最多可投票 6 票，多次投票以最新一次投票结果为准，不选择科技提交投票可以撤回投票或投空票。": "Each person may cast up to 6 votes. The latest submission is used; submit without selecting technologies to withdraw or submit a blank ballot.",
      "{tasks} 个任务 · {permissions} 项权限": "{tasks} tasks · {permissions} permissions",
      "从市政厅沙盘更新成员贡献数据。": "Update member contributions from the town-hall sandbox.",
      "更新成员离线时间与公共斩杀预警数据。": "Update member offline times and public removal-warning data.",
      "成员职业、庄园、同居、公职与当前名单同步。": "Sync member professions, manors, roommates, officers, and the current roster.",
      "更新周活跃点": "Update weekly activity points",
      "读取营地周计划中的活跃排行并更新成员周活跃点": "Read the camp weekly activity ranking and update member points",
      "周活跃点": "Weekly activity points",
      "执行更新周活跃点": "Run weekly activity update",
      "科技投票、固定科技、历史归档与 Agent 科技切换任务。": "Technology voting, fixed choices, vote archives, and Agent technology switching.",
      "组建巡逻队、困难路线与定时古籍分享。": "Build patrol teams, run hard routes, and schedule book-defense sharing.",
      "更新职业、庄园、同居与公职，并刷新当前名单": "Update professions, manors, roommates, and officers, then refresh the current roster.",
      "执行更新贡献": "Run contribution update",
      "执行更新斩杀预警": "Run removal-warning update",
      "执行更新成员资料": "Run member-profile update",
      "执行营地巡逻": "Run camp patrol",
      "执行更新科技": "Run technology update",
      "已停用": "Disabled",
      "停用": "Disable",
      "{task} / {state}": "{task} / {state}",
      "第一行科技最大开放数量": "Maximum technologies open in row 1",
      "第二行科技最大开放数量": "Maximum technologies open in row 2",
      "科技预测": "Technology projection",
      "固定科技优先，按当前票数补足": "Fixed technologies first, then fill with current votes",
      "当前投票日期显示固定科技与投票科技；其余日期显示已设置的固定科技。": "The current voting date shows fixed and voted technologies; other dates show configured fixed technologies.",
      "暂无科技描述": "No technology description",
      "科技所在行由营地科技类型自动决定": "The technology row is determined automatically by the camp technology type",
      "投票截止后至每日刷新前不可修改当前固定科技": "Current fixed technologies cannot be changed after voting closes and before the daily reset",
      "投票截止后至每日刷新前不可修改当前投票配置": "Current voting settings cannot be changed after voting closes and before the daily reset",
      "{lane}最多固定 {limit} 项": "Up to {limit} fixed technologies in {lane}",
      "军事科技行": "Military technology row",
      "农业科技行": "Agricultural technology row",
      "工业科技行": "Industrial technology row",
      "其他科技行": "Other-technology row",
      "有 {count} 个分区未保存": "{count} sections have unsaved changes",
      "科技配置尚未保存": "Technology settings have unsaved changes",
      "没有符合条件的临时 Key。": "No temporary keys match these filters.",
      "搜索姓名、职业、同居": "Search name, profession, or roommate",
      "没有符合条件的申请。": "No applications match these filters.",
      "正在处理并发送邮件…": "Processing and sending email…",
      "申请已通过并发送邮件": "Application approved and email sent",
      "申请已拒绝并发送通知": "Application rejected and notification sent",
      "申请已处理，但邮件发送失败：{error}": "Application processed, but email sending failed: {error}",
      "测试邮件已发送": "Test email sent",
      "SMTP 配置已保存": "SMTP settings saved",
      "已配置；留空则保留现有密码": "Configured; leave blank to keep the existing password",
      "尚未配置密码": "No password configured",
      "已生成：{code}": "Generated: {code}",
      "延期": "Renewal",
      "重新发行": "Reissue",
      "新申请": "New application"
