      "任务时间前后活跃窗口（分钟）": "任務時間前後活躍視窗（分鐘）",
      "空闲轮询可设为 300–600 秒；实际任务窗口内建议 15–30 秒，仅保留确实会执行任务的窗口。任务执行中轮询可保持 10–15 秒，以兼顾响应速度。": "閒置輪詢可設為 300–600 秒；實際任務視窗內建議 15–30 秒，只保留確實會執行任務的視窗。執行任務中可維持 10–15 秒以兼顧反應速度。",
      "下方 JSON 只控制本地 Agent 何时向 Worker 请求任务及请求间隔，不是任务执行时间；窗口外会使用默认空闲轮询。": "下方 JSON 只控制本機 Agent 何時向 Worker 請求任務與請求間隔，不是任務執行時間；視窗外會使用預設閒置輪詢。",
      "Agent 会从任务计划中的启用任务时间自动生成活跃窗口，默认覆盖每个任务时间前后 15 分钟；窗口内保持 Workers-Agent 交互，窗口外进入懒惰状态并直接睡到下一个窗口。": "Agent 會從已啟用任務時間自動產生活躍視窗，預設涵蓋每個任務時間前後 15 分鐘；視窗內保持連線，視窗外直接睡到下一個視窗。",
      "手动点击 Mac Agent 左下角“恢复活跃”可随时解除懒惰；再次点击“解除活跃”恢复懒惰。定时任务窗口仍会自动唤醒，进入窗口后先向 Workers 请求最新计划再开始工作。": "手動點擊 Mac Agent 左下角「恢復活躍」可解除閒置；再次點擊「解除活躍」返回閒置。定時視窗仍會自動喚醒，進入後先向 Workers 取得最新計畫。",
